3	import com.example.blog.shared.erro.ConflitoException;
4	import com.example.blog.shared.erro.CredenciaisInvalidasException;
5	import com.example.blog.shared.erro.MensagensErro;
6	import com.example.blog.shared.erro.TokenInvalidoException;
7	import com.example.blog.shared.erro.ValidacaoException;
8	import com.example.blog.shared.seguranca.TokenService;
9	import com.example.blog.usuario.persistence.Usuario;
10	import com.example.blog.usuario.persistence.UsuarioRepository;
11	import java.time.Clock;
12	import java.time.Instant;
13	import java.util.List;
14	import java.util.Locale;
15	import java.util.Map;
16	import java.util.Optional;
17	import java.util.TreeMap;
18	import org.hibernate.exception.ConstraintViolationException;
19	import org.springframework.dao.DataIntegrityViolationException;
20	import org.springframework.security.crypto.password.PasswordEncoder;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	/**
25	 * Regras de conta: cadastro, login, consulta e atualização do usuário autenticado.
26	 *
27	 * <p>Toda resposta de sucesso traz um token novo, emitido por {@link TokenService}.
28	 */
29	@Service
30	public class UsuarioService {
31	
32	    private static final String CAMPO_EMAIL = "email";
33	    private static final String CAMPO_USERNAME = "username";
34	    private static final Map<String, String> CAMPO_POR_RESTRICAO = Map.of(
35	            "uq_usuario_email", CAMPO_EMAIL,
36	            "uq_usuario_username", CAMPO_USERNAME);
37	
38	    private final UsuarioRepository repository;
39	    private final PasswordEncoder passwordEncoder;
40	    private final TokenService tokenService;
41	    private final Clock clock;
42	
43	    public UsuarioService(UsuarioRepository repository, PasswordEncoder passwordEncoder, TokenService tokenService,
44	            Clock clock) {
45	        this.repository = repository;
46	        this.passwordEncoder = passwordEncoder;
47	        this.tokenService = tokenService;
48	        this.clock = clock;
49	    }
50	
51	    /**
52	     * Cria uma conta.
53	     *
54	     * @throws ConflitoException se o e-mail (sem diferenciar maiúsculas) ou o username já estiverem em uso
55	     */
56	    @Transactional
57	    public UsuarioAutenticadoDto cadastrar(String username, String email, String senha) {
58	        String usernameNormalizado = username.trim();
59	        String emailNormalizado = email.trim();
60	        Map<String, List<String>> conflitos = new TreeMap<>();
61	        if (repository.existsByEmailIgnoreCase(emailNormalizado)) {
62	            conflitos.put(CAMPO_EMAIL, List.of(MensagensErro.JA_EM_USO));
63	        }
64	        if (repository.existsByUsername(usernameNormalizado)) {
65	            conflitos.put(CAMPO_USERNAME, List.of(MensagensErro.JA_EM_USO));
66	        }
67	        if (!conflitos.isEmpty()) {
68	            throw new ConflitoException(conflitos);
69	        }
70	        Usuario usuario = new Usuario(usernameNormalizado, emailNormalizado, passwordEncoder.encode(senha),
71	                Instant.now(clock));
72	        try {
73	            return paraDto(repository.saveAndFlush(usuario));
74	        } catch (DataIntegrityViolationException excecao) {
75	            throw new ConflitoException(Map.of(campoDaViolacao(excecao), List.of(MensagensErro.JA_EM_USO)));
76	        }
77	    }
78	
79	    /**
80	     * Autentica por e-mail (sem diferenciar maiúsculas) e senha.
81	     *
82	     * @throws CredenciaisInvalidasException se o e-mail não existir ou a senha não conferir
83	     */
84	    @Transactional(readOnly = true)
85	    public UsuarioAutenticadoDto autenticar(String email, String senha) {
86	        Optional<Usuario> usuario = repository.findByEmailIgnoreCase(email.trim());
87	        if (usuario.isEmpty() || !passwordEncoder.matches(senha, usuario.get().getSenhaHash())) {
88	            throw new CredenciaisInvalidasException();
89	        }
90	        return paraDto(usuario.get());
91	    }
92	
93	    /**
94	     * @throws TokenInvalidoException se o usuário do token não existir
95	     */
96	    @Transactional(readOnly = true)
97	    public UsuarioAutenticadoDto buscarAtual(Long id) {
98	        return paraDto(buscarPorIdDoToken(id));
99	    }
100	
101	    /**
102	     * Aplica somente os campos presentes na atualização.
103	     *
104	     * @throws TokenInvalidoException se o usuário do token não existir
105	     * @throws ValidacaoException se o e-mail ou o username pertencerem a outra conta
106	     */
107	    @Transactional
108	    public UsuarioAutenticadoDto atualizar(Long id, AtualizacaoUsuario atualizacao) {
109	        Usuario usuario = buscarPorIdDoToken(id);
110	        verificarUnicidade(id, atualizacao);
111	        if (atualizacao.email().presente()) {
112	            usuario.alterarEmail(atualizacao.email().valor());
113	        }
114	        if (atualizacao.username().presente()) {
115	            usuario.alterarUsername(atualizacao.username().valor());
116	        }
117	        if (atualizacao.senha().presente()) {
118	            usuario.alterarSenhaHash(passwordEncoder.encode(atualizacao.senha().valor()));
119	        }
120	        if (atualizacao.bio().presente()) {
121	            usuario.alterarBio(atualizacao.bio().valor());
122	        }
123	        if (atualizacao.imagem().presente()) {
124	            usuario.alterarImagem(atualizacao.imagem().valor());
125	        }
126	        usuario.registrarAlteracao(Instant.now(clock));
127	        try {
128	            return paraDto(repository.saveAndFlush(usuario));
129	        } catch (DataIntegrityViolationException excecao) {
130	            throw new ValidacaoException(Map.of(campoDaViolacao(excecao), List.of(MensagensErro.JA_EM_USO)));
131	        }
132	    }
133	
134	    private void verificarUnicidade(Long id, AtualizacaoUsuario atualizacao) {
135	        Map<String, List<String>> conflitos = new TreeMap<>();
136	        if (atualizacao.email().presente()
137	                && repository.existsByEmailIgnoreCaseAndIdNot(atualizacao.email().valor(), id)) {
138	            conflitos.put(CAMPO_EMAIL, List.of(MensagensErro.JA_EM_USO));
139	        }
140	        if (atualizacao.username().presente()
141	                && repository.existsByUsernameAndIdNot(atualizacao.username().valor(), id)) {
142	            conflitos.put(CAMPO_USERNAME, List.of(MensagensErro.JA_EM_USO));
143	        }
144	        if (!conflitos.isEmpty()) {
145	            throw new ValidacaoException(conflitos);
146	        }
147	    }
148	
149	    private Usuario buscarPorIdDoToken(Long id) {
150	        return repository.findById(id).orElseThrow(TokenInvalidoException::new);
151	    }
152	
153	    private UsuarioAutenticadoDto paraDto(Usuario usuario) {
154	        return new UsuarioAutenticadoDto(usuario.getId(), usuario.getEmail(), usuario.getUsername(),
155	                usuario.getBio(), usuario.getImagem(), tokenService.emitir(usuario.getId()));
156	    }
157	
158	    /** Identifica o campo pela restrição violada; violações não relacionadas à unicidade são relançadas. */
159	    private static String campoDaViolacao(DataIntegrityViolationException excecao) {
160	        Throwable causa = excecao;
161	        while (causa != null) {
162	            if (causa instanceof ConstraintViolationException violacao && violacao.getConstraintName() != null) {
163	                String campo = CAMPO_POR_RESTRICAO.get(violacao.getConstraintName().toLowerCase(Locale.ROOT));
164	                if (campo != null) {
165	                    return campo;
166	                }
167	            }
168	            causa = causa.getCause();
169	        }
170	        throw excecao;
171	    }
172	}
