package com.example.blog.shared.erro;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.FieldError;
import org.springframework.web.ErrorResponse;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Ponto único de conversão de exceções em respostas {@code {"errors":{...}}} do contrato.
 */
@RestControllerAdvice
public class ManipuladorDeErros {

    private static final Logger log = LoggerFactory.getLogger(ManipuladorDeErros.class);
    private static final String PREFIXO_USER = MensagensErro.CHAVE_USER + ".";
    private static final HttpStatus ENTIDADE_NAO_PROCESSAVEL = HttpStatus.UNPROCESSABLE_CONTENT;

    @ExceptionHandler(MethodArgumentNotValidException.class)
    ResponseEntity<ErrosResponse> tratarValidacao(MethodArgumentNotValidException excecao) {
        Map<String, TreeSet<String>> agrupados = new TreeMap<>();
        for (FieldError erro : excecao.getBindingResult().getFieldErrors()) {
            if (MensagensErro.CHAVE_USER.equals(erro.getField())) {
                return responder(ENTIDADE_NAO_PROCESSAVEL,
                        ErrosResponse.de(MensagensErro.CHAVE_BODY, MensagensErro.CORPO_VAZIO));
            }
            String campo = erro.getField().startsWith(PREFIXO_USER)
                    ? erro.getField().substring(PREFIXO_USER.length())
                    : erro.getField();
            agrupados.computeIfAbsent(campo, chave -> new TreeSet<>()).add(erro.getDefaultMessage());
        }
        Map<String, List<String>> erros = new TreeMap<>();
        agrupados.forEach((campo, mensagens) -> erros.put(campo, priorizarVazio(mensagens)));
        return responder(ENTIDADE_NAO_PROCESSAVEL, new ErrosResponse(erros));
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    ResponseEntity<ErrosResponse> tratarCorpoIlegivel(HttpMessageNotReadableException excecao) {
        return responder(ENTIDADE_NAO_PROCESSAVEL,
                ErrosResponse.de(MensagensErro.CHAVE_BODY, MensagensErro.CORPO_VAZIO));
    }

    @ExceptionHandler(ValidacaoException.class)
    ResponseEntity<ErrosResponse> tratarValidacaoDeRegra(ValidacaoException excecao) {
        return responder(ENTIDADE_NAO_PROCESSAVEL, new ErrosResponse(excecao.getErros()));
    }

    @ExceptionHandler(ConflitoException.class)
    ResponseEntity<ErrosResponse> tratarConflito(ConflitoException excecao) {
        return responder(HttpStatus.CONFLICT, new ErrosResponse(excecao.getErros()));
    }

    @ExceptionHandler(CredenciaisInvalidasException.class)
    ResponseEntity<ErrosResponse> tratarCredenciaisInvalidas(CredenciaisInvalidasException excecao) {
        return responder(HttpStatus.UNAUTHORIZED,
                ErrosResponse.de(MensagensErro.CHAVE_CREDENCIAIS, MensagensErro.INVALIDO));
    }

    @ExceptionHandler(RecursoNaoEncontradoException.class)
    ResponseEntity<ErrosResponse> tratarNaoEncontrado(RecursoNaoEncontradoException excecao) {
        return responder(HttpStatus.NOT_FOUND, ErrosResponse.de(excecao.getChave(), MensagensErro.NAO_ENCONTRADO));
    }

    @ExceptionHandler(TokenInvalidoException.class)
    ResponseEntity<ErrosResponse> tratarTokenInvalido(TokenInvalidoException excecao) {
        return responder(HttpStatus.UNAUTHORIZED,
                ErrosResponse.de(MensagensErro.CHAVE_TOKEN, MensagensErro.INVALIDO));
    }

    @ExceptionHandler(Exception.class)
    ResponseEntity<ErrosResponse> tratarInesperado(Exception excecao) {
        if (excecao instanceof ErrorResponse erroDoFramework) {
            return tratarErroDoFramework(erroDoFramework.getStatusCode());
        }
        log.error("Erro inesperado ao processar a requisição", excecao);
        return responder(HttpStatus.INTERNAL_SERVER_ERROR,
                ErrosResponse.de(MensagensErro.CHAVE_SERVIDOR, MensagensErro.ERRO_INTERNO));
    }

    private ResponseEntity<ErrosResponse> tratarErroDoFramework(HttpStatusCode status) {
        HttpStatus conhecido = HttpStatus.resolve(status.value());
        String motivo = conhecido == null ? "error" : conhecido.getReasonPhrase().toLowerCase(Locale.ROOT);
        return responder(status, ErrosResponse.de(MensagensErro.CHAVE_REQUISICAO, motivo));
    }

    /** Campo vazio gera só "can't be blank", mesmo que outra regra (como formato de e-mail) também falhe. */
    private static List<String> priorizarVazio(TreeSet<String> mensagens) {
        if (mensagens.contains(MensagensErro.NAO_PODE_SER_VAZIO)) {
            return List.of(MensagensErro.NAO_PODE_SER_VAZIO);
        }
        return new ArrayList<>(mensagens);
    }

    private static ResponseEntity<ErrosResponse> responder(HttpStatusCode status, ErrosResponse corpo) {
        return ResponseEntity.status(status).contentType(MediaType.APPLICATION_JSON).body(corpo);
    }
}

package com.example.blog.usuario.web;

import com.example.blog.shared.erro.MensagensErro;
import com.example.blog.shared.erro.ValidacaoException;
import com.example.blog.usuario.service.AtualizacaoUsuario;
import com.example.blog.usuario.service.CampoAtualizado;
import jakarta.validation.Validator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.stereotype.Component;
import tools.jackson.databind.JsonNode;

/**
 * Converte o corpo do {@code PUT /api/user} em {@link AtualizacaoUsuario}, acumulando todos os erros de
 * validação em uma única {@link ValidacaoException}.
 *
 * <p>Campos aceitos: {@code email}, {@code username}, {@code password}, {@code bio} e {@code image}. Campos
 * desconhecidos são ignorados.
 */
@Component
public class AtualizacaoUsuarioMapper {

    private static final String CAMPO_EMAIL = "email";
    private static final String CAMPO_USERNAME = "username";
    private static final String CAMPO_PASSWORD = "password";
    private static final String CAMPO_BIO = "bio";
    private static final String CAMPO_IMAGE = "image";
    private static final List<String> CAMPOS_ACEITOS =
            List.of(CAMPO_EMAIL, CAMPO_USERNAME, CAMPO_PASSWORD, CAMPO_BIO, CAMPO_IMAGE);

    private final Validator validator;

    public AtualizacaoUsuarioMapper(Validator validator) {
        this.validator = validator;
    }

    /**
     * @throws ValidacaoException com {@code body} se {@code user} não for um objeto, com {@code user} se nenhum
     *     campo aceito vier, ou com os erros de cada campo
     */
    public AtualizacaoUsuario converter(AtualizacaoRequest requisicao) {
        JsonNode user = requisicao == null ? null : requisicao.user();
        if (user == null || !user.isObject()) {
            throw ValidacaoException.de(MensagensErro.CHAVE_BODY, MensagensErro.CORPO_VAZIO);
        }
        if (CAMPOS_ACEITOS.stream().noneMatch(user::has)) {
            throw ValidacaoException.de(MensagensErro.CHAVE_USER, MensagensErro.NAO_PODE_SER_VAZIO);
        }
        Map<String, List<String>> erros = new TreeMap<>();
        CampoAtualizado<String> email = textoObrigatorio(user, CAMPO_EMAIL, erros);
        if (email.presente() && email.valor() != null && !isEmailValido(email.valor())) {
            erros.put(CAMPO_EMAIL, List.of(MensagensErro.INVALIDO));
        }
        CampoAtualizado<String> username = textoObrigatorio(user, CAMPO_USERNAME, erros);
        CampoAtualizado<String> senha = senha(user, erros);
        CampoAtualizado<String> bio = textoOpcional(user, CAMPO_BIO, erros);
        CampoAtualizado<String> imagem = textoOpcional(user, CAMPO_IMAGE, erros);
        if (!erros.isEmpty()) {
            throw new ValidacaoException(erros);
        }
        return new AtualizacaoUsuario(email, username, senha, bio, imagem);
    }

    /** E-mail e username: se enviados, precisam ser texto não vazio; o valor é aparado. */
    private static CampoAtualizado<String> textoObrigatorio(JsonNode user, String campo,
            Map<String, List<String>> erros) {
        if (!user.has(campo)) {
            return CampoAtualizado.ausente();
        }
        String texto = textoNaoVazio(user.get(campo), campo, erros);
        return texto == null ? CampoAtualizado.ausente() : CampoAtualizado.de(texto.trim());
    }

    /** Senha: se enviada, precisa ser texto não vazio; o valor é mantido como enviado. */
    private static CampoAtualizado<String> senha(JsonNode user, Map<String, List<String>> erros) {
        if (!user.has(CAMPO_PASSWORD)) {
            return CampoAtualizado.ausente();
        }
        String texto = textoNaoVazio(user.get(CAMPO_PASSWORD), CAMPO_PASSWORD, erros);
        return texto == null ? CampoAtualizado.ausente() : CampoAtualizado.de(texto);
    }

    /** Bio e imagem: aceitam texto ou {@code null} (que limpa o valor). */
    private static CampoAtualizado<String> textoOpcional(JsonNode user, String campo,
            Map<String, List<String>> erros) {
        if (!user.has(campo)) {
            return CampoAtualizado.ausente();
        }
        JsonNode valor = user.get(campo);
        if (valor.isNull()) {
            return CampoAtualizado.de(null);
        }
        if (!valor.isString()) {
            erros.put(campo, List.of(MensagensErro.INVALIDO));
            return CampoAtualizado.ausente();
        }
        return CampoAtualizado.de(valor.stringValue());
    }

    /** Devolve o texto, ou {@code null} depois de registrar o erro do campo. */
    private static String textoNaoVazio(JsonNode valor, String campo, Map<String, List<String>> erros) {
        if (valor.isNull() || (valor.isString() && valor.stringValue().isBlank())) {
            erros.put(campo, List.of(MensagensErro.NAO_PODE_SER_VAZIO));
            return null;
        }
        if (!valor.isString()) {
            erros.put(campo, List.of(MensagensErro.INVALIDO));
            return null;
        }
        return valor.stringValue();
    }

    /** Mesma regra de formato do cadastro ({@code @Email} de {@link NovoUsuario#email()}). */
    private boolean isEmailValido(String email) {
        return validator.validateValue(NovoUsuario.class, CAMPO_EMAIL, email).isEmpty();
    }
}

